{"CommandLine":"node -e '
async function test() {
  const baseApi = "http://localhost:5123";
  const baseWeb = "http://localhost:3000";

  console.log("1. Testing Frontend Web Server HTML response...");
  const webResp = await fetch(baseWeb);
  const html = await webResp.text();
  if (!html.includes("Bursa Büyükşehir Belediyesi")) throw new Error("Frontend did not return correct title");
  console.log("   Frontend HTML loaded successfully!");

  console.log("2. Testing Citizen Registration...");
  const email = `citizen_${Date.now()}@bursa.bel.tr`;
  const regResp = await fetch(`${baseApi}/api/auth/register`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      firstName: "Hasan",
      lastName: "Kaya",
      email,
      phoneNumber: "5551234567",
      password: "Password123!"
    })
  });
  if (!regResp.ok) throw new Error(`Registration failed: ${regResp.status} ${await regResp.text()}`);
  console.log("   Citizen registration succeeded!");

  console.log("3. Testing Citizen Login...");
  const loginResp = await fetch(`${baseApi}/api/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password: "Password123!" })
  });
  const citizenAuth = await loginResp.json();
  console.log(`   Logged in as ${citizenAuth.user.firstName} ${citizenAuth.user.lastName} (Role: ${citizenAuth.user.role})`);

  console.log("4. Testing Categories reference lookup...");
  const catResp = await fetch(`${baseApi}/api/categories`, {
    headers: { "Authorization": `Bearer ${citizenAuth.accessToken}` }
  });
  const categories = await catResp.json();
  console.log(`   Fetched ${categories.length} categories. First: ${categories[0].name}`);

  console.log("5. Testing Service Request Creation...");
  const createResp = await fetch(`${baseApi}/api/service-requests`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${citizenAuth.accessToken}`
    },
    body: JSON.stringify({
      title: "Nilüfer Sokak Aydınlatma Arızası",
      categoryId: categories[0].id,
      description: "Sokak lambası çalışmıyor.",
      addressText: "Ataevler Mah. Nilüfer / Bursa"
    })
  });
  const created = await createResp.json();
  console.log(`   Created service request ID: ${created.id}`);

  console.log("6. Testing Manager Login...");
  const mgrLogin = await fetch(`${baseApi}/api/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: "manager@bursa.bel.tr", password: "Demo12345!" })
  });
  const mgrAuth = await mgrLogin.json();
  console.log(`   Logged in as Manager: ${mgrAuth.user.email}`);

  console.log("7. Testing Manager Review...");
  await fetch(`${baseApi}/api/manager/service-requests/${created.id}/review`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${mgrAuth.accessToken}` }
  });
  console.log("   Review started!");

  console.log("8. Testing Departments and Employee Lookups...");
  const deptResp = await fetch(`${baseApi}/api/departments`, {
    headers: { "Authorization": `Bearer ${mgrAuth.accessToken}` }
  });
  const depts = await deptResp.json();
  const empResp = await fetch(`${baseApi}/api/departments/${depts[0].id}/employees`, {
    headers: { "Authorization": `Bearer ${mgrAuth.accessToken}` }
  });
  const emps = await empResp.json();
  console.log(`   Department: ${depts[0].name}, Employee: ${emps[0].fullName}`);

  console.log("9. Testing Assignment...");
  await fetch(`${baseApi}/api/manager/service-requests/${created.id}/assign`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${mgrAuth.accessToken}`
    },
    body: JSON.stringify({
      departmentId: depts[0].id,
      employeeId: emps[0].id,
      priority: "High"
    })
  });
  console.log("   Assigned successfully!");

  console.log("10. Testing Employee Login...");
  const empLogin = await fetch(`${baseApi}/api/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: "employee1@bursa.bel.tr", password: "Demo12345!" })
  });
  const empAuth = await empLogin.json();

  console.log("11. Testing Employee Start Work...");
  await fetch(`${baseApi}/api/employee/service-requests/${created.id}/start`, {
    method: "POST",
    headers: { "Authorization": `Bearer ${empAuth.accessToken}` }
  });
  console.log("   Work started (Status: InProgress)!");

  console.log("12. Testing Employee Resolve...");
  await fetch(`${baseApi}/api/employee/service-requests/${created.id}/resolve`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${empAuth.accessToken}`
    },
    body: JSON.stringify({ note: "Armatür yenilendi ve hat testi yapıldı." })
  });
  console.log("   Resolved successfully!");

  console.log("13. Testing Manager Close...");
  await fetch(`${baseApi}/api/manager/service-requests/${created.id}/close`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${mgrAuth.accessToken}`
    },
    body: JSON.stringify({ note: "Saha kontrolü onaylandı." })
  });
  console.log("   Closed successfully!");

  console.log("14. Verifying Final Request State...");
  const finalResp = await fetch(`${baseApi}/api/manager/service-requests/${created.id}`, {
    headers: { "Authorization": `Bearer ${mgrAuth.accessToken}` }
  });
  const finalDetail = await finalResp.json();
  console.log(`   Final Status: ${finalDetail.status}`);
  console.log(`   Total Status History Entries: ${finalDetail.statusHistory.length}`);
  finalDetail.statusHistory.forEach((h, i) => {
    console.log(`     ${i + 1}. ${h.oldStatus} -> ${h.newStatus} (Note: ${h.note || "none"})`);
  });

  if (finalDetail.status !== "Closed" || finalDetail.statusHistory.length !== 5) {
    throw new Error("Final verification failed!");
  }

  console.log("\nALL SMOKE TEST VERIFICATIONS PASSED 100%!");
}

test().catch(err => {
  console.error("Test error:", err);
  process.exit(1);
});
